using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class GuiziReflectionFix{
 const string Done="D:/-11-scene3-audit/guizi-fixed.txt";static double next;static GuiziReflectionFix(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+5;if(File.Exists(Done)||EditorApplication.isUpdating||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;Run();}
 static void Run(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.name!="scene3")return;try{var rs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.name=="guizi1"||r.name=="guizi2").ToArray();if(rs.Length!=2)throw new Exception("Expected guizi1 and guizi2, found "+rs.Length);EditorSceneManager.SaveScene(s);File.Copy(s.path,"D:/-11-scene3-audit/scene3.before-guizi-lighting.unity",true);var report=new List<string>();
 foreach(var r in rs){var b=r.bounds;string helperName=r.name+" Reflection";var go=s.GetRootGameObjects().FirstOrDefault(g=>g.name==helperName);if(!go){go=new GameObject(helperName);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(go,s);Undo.RegisterCreatedObjectUndo(go,"Match Blender cabinet reflections");}go.transform.position=b.center+Vector3.right*.3f;var probe=go.GetComponent<ReflectionProbe>();if(!probe)probe=go.AddComponent<ReflectionProbe>();probe.mode=UnityEngine.Rendering.ReflectionProbeMode.Custom;probe.boxProjection=true;probe.size=b.size+new Vector3(.85f,.7f,.7f);probe.center=new Vector3(-.15f,0,0);probe.blendDistance=.1f;probe.importance=100;probe.intensity=1.65f;probe.hdr=true;
 var cap=new GameObject("Cabinet reflection capture"){hideFlags=HideFlags.HideAndDontSave};var c=cap.AddComponent<Camera>();c.enabled=false;c.transform.position=b.center+new Vector3(.45f,.18f,0);c.nearClipPlane=.015f;c.farClipPlane=30;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.22f,.23f,.25f);c.allowHDR=true;string cubePath="Assets/BlenderScene3/Materials/"+r.name+"Environment.asset";var cube=AssetDatabase.LoadAssetAtPath<Cubemap>(cubePath);if(!cube){cube=new Cubemap(128,TextureFormat.RGBAHalf,true);AssetDatabase.CreateAsset(cube,cubePath);}try{if(!c.RenderToCubemap(cube))throw new Exception("Reflection capture failed: "+r.name);}finally{UnityEngine.Object.DestroyImmediate(cap);}EditorUtility.SetDirty(cube);probe.customBakedTexture=cube;Undo.RecordObject(r,"Use local cabinet reflection");r.reflectionProbeUsage=UnityEngine.Rendering.ReflectionProbeUsage.Simple;r.probeAnchor=go.transform;PrefabUtility.RecordPrefabInstancePropertyModifications(r);
 var lightName=r.name+" Soft Key";var lg=s.GetRootGameObjects().FirstOrDefault(g=>g.name==lightName);if(!lg){lg=new GameObject(lightName);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(lg,s);Undo.RegisterCreatedObjectUndo(lg,"Add cabinet soft key");}lg.transform.position=b.center+new Vector3(.6f,.45f,-.2f);lg.transform.LookAt(b.center);var l=lg.GetComponent<Light>();if(!l)l=lg.AddComponent<Light>();l.type=LightType.Spot;l.spotAngle=70;l.range=1.8f;l.intensity=.75f;l.color=new Color(1,.97f,.94f);l.renderMode=LightRenderMode.ForcePixel;l.shadows=LightShadows.Soft;l.shadowCustomResolution=512;l.shadowBias=.002f;l.shadowNormalBias=.01f;
 report.Add(r.name+"|material="+AssetDatabase.GetAssetPath(r.sharedMaterial)+"|metallic="+r.sharedMaterial.GetFloat("_Metallic")+"|localReflection="+cubePath+"|reflectionIntensity="+probe.intensity+"|keyIntensity="+l.intensity);
 }
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllLines(Done,report);
 }catch(Exception e){File.WriteAllText("D:/-11-scene3-audit/guizi-fix-error.txt",e.ToString());}}
}
